#include <cassert>
#include <cstdio>
#include <vector>
#include "../peripheral_spi/src/lcd.h"
static std::vector<uint8_t> transfer(Peripheral::Lcd& lcd,uint32_t now,unsigned count){std::vector<uint8_t> bytes;lcd.poll(now);assert(lcd.busy()&&(TWCR&_BV(TWSTA)));TWSR=0x08;TWCR=_BV(TWINT)|_BV(TWEN);lcd.poll(now);assert(TWDR==(PERIPHERAL_LCD_ADDRESS<<1));TWSR=0x18;lcd.poll(now);bytes.push_back(uint8_t(TWDR));for(unsigned i=1;i<count;i++){TWSR=0x28;lcd.poll(now);bytes.push_back(uint8_t(TWDR));}TWSR=0x28;lcd.poll(now);assert(TWCR&_BV(TWSTO));TWCR=_BV(TWEN);lcd.poll(now);assert(!lcd.busy());return bytes;}
int main(){Peripheral::Lcd lcd;Peripheral::Engine engine;lcd.setup(0);lcd.poll(39);assert(!lcd.busy());auto first=transfer(lcd,40,3);uint8_t v=_BV(PERIPHERAL_LCD_BL_BIT)|_BV(PERIPHERAL_LCD_D4_BIT)|_BV(PERIPHERAL_LCD_D5_BIT);assert(first[0]==v&&first[1]==(v|_BV(PERIPHERAL_LCD_EN_BIT))&&first[2]==v);lcd.poll(44);assert(!lcd.busy());transfer(lcd,45,3);transfer(lcd,46,3);auto four=transfer(lcd,47,3);assert(four[0]==(_BV(PERIPHERAL_LCD_BL_BIT)|_BV(PERIPHERAL_LCD_D5_BIT)));transfer(lcd,48,6);transfer(lcd,49,6);transfer(lcd,50,6);transfer(lcd,52,6);lcd.poll(53);assert(!lcd.busy());lcd.display(engine);transfer(lcd,54,6);auto data=transfer(lcd,55,6);assert(data[0]&_BV(PERIPHERAL_LCD_RS_BIT));assert(!(data[0]&_BV(PERIPHERAL_LCD_RW_BIT)));assert(!lcd.fault());lcd.poll(56);assert(lcd.busy());TWSR=0x08;lcd.poll(56);TWSR=0x20;lcd.poll(56);assert(lcd.fault()&&!lcd.busy());lcd.poll(1055);assert(!lcd.busy());lcd.poll(1056);assert(lcd.busy());TWCR&=uint8_t(~_BV(TWINT));lcd.poll(1061);assert(lcd.fault()&&!lcd.busy());puts("PASS LCD wake/timing/PCF mapping/address/data/NACK/timeout/retry");}
